use core.files as files
use core.process as process
use core.text as text

struct Section {
    name: String
    inherit: String
    keys: [String]
    values: [String]
}

fn run() {
    path :: process.argv().get(1) ?? panic("missing path")
    input :: files.read(path) ?? panic("read failed")
    sections := [Section]{}
    current := -1

    loop row in input.lines() {
        line :: ~row.trim()
        if line.is_empty() {
            next
        }
        if line.contains("[") {
            header :: text.splitn(line, "]", 2)
            title :: header.get(0) ?? panic("invalid section header")
            name_parts :: text.splitn(title, "[", 2)
            section_name :: name_parts.get(1) ?? panic("invalid section header")
            section :: Section{
                name: section_name,
                inherit: "",
                keys: [String]{},
                values: [String]{},
            }
            sections.push(section)
            current = sections.len() - 1
        } else {
            if current < 0 {
                panic("field outside section")
            }
            pair :: text.splitn(line, "=", 2)
            key :: (pair.get(0) ?? panic("invalid field")).trim()
            raw_value :: pair.get(1) ?? panic("invalid field")
            quoted :: text.splitn(raw_value.trim(), "\"", 3)
            value :: quoted.get(1) ?? panic("invalid quoted value")
            if key.is_empty() {
                panic("invalid field")
            }
            if key == "inherits" {
                sections[current].inherit = value
            } else {
                duplicate := false
                loop i in 0..<sections[current].keys.len() {
                    if sections[current].keys[i] == key {
                        duplicate = true
                    }
                }
                if duplicate {
                    panic("duplicate field {key} in section {sections[current].name}")
                }
                sections[current].keys.push(key)
                sections[current].values.push(value)
            }
        }
    }

    loop section_index in 0..<sections.len() {
        resolved_keys := [String]{}
        resolved_values := [String]{}
        inherit_name :: sections[section_index].inherit
        if !inherit_name.is_empty() {
            base_index := -1
            loop candidate in 0..<sections.len() {
                if sections[candidate].name == inherit_name {
                    base_index = candidate
                }
            }
            if base_index < 0 {
                panic("unknown inherited section {inherit_name}")
            }
            if !sections[base_index].inherit.is_empty() {
                panic("inheritance is only one level")
            }
            loop i in 0..<sections[base_index].keys.len() {
                resolved_keys.push(sections[base_index].keys[i])
                resolved_values.push(sections[base_index].values[i])
            }
        }
        loop i in 0..<sections[section_index].keys.len() {
            key :: sections[section_index].keys[i]
            value :: sections[section_index].values[i]
            replaced := false
            loop j in 0..<resolved_keys.len() {
                if resolved_keys[j] == key {
                    resolved_values[j] = ~value
                    replaced = true
                }
            }
            if !replaced {
                resolved_keys.push(key)
                resolved_values.push(value)
            }
        }
        loop i in 0..<resolved_keys.len() {
            print("{sections[section_index].name}.{resolved_keys[i]}={resolved_values[i]}")
        }
    }
}
